def crc16(data: Integer[Array, '16'], poly: Integer=33800):
    bprobe_trace = []
    '\n    CRC-16-CCITT Algorithm\n    '
    crc = 65535
    for b in data:
        cur_byte = 255 & b
        for _ in range(0, 8):
            if crc & 1 ^ cur_byte & 1:
                crc = crc >> 1 ^ poly
            else:
                crc >>= 1
            cur_byte >>= 1
    crc = ~crc & 65535
    crc = crc << 8 | crc >> 8 & 255
    return bprobe_trace
